    return (False, None)
s = r

w = e + s
# Check DF is within (s, w)
if not (s + 1 <= x <= w - 1):
    # F must lie strictly between D and C, and ensure h > y (by s < x)
    return (False, None)

# Compute h exactly as a reduced fraction: h = (y^2 - w^2 + 2 w x) / (2 y)
def gcd(a, b):
